{
    int low{ 0 };
    int high{ static_cast<int>(sorted.size()) - 1 };
    // while (low <= high) ...
    return -1;
}

solution.solution.cpp:
#include <vector>

int binarySearch(const std::vector<int>& sorted, int target)
{
    int low{ 0 };
    int high{ static_cast<int>(sorted.size()) - 1 };
    while (low <= high)
    {
        const int middle{ low + (high - low) / 2 };
        const int value{ sorted[static_cast<std::size_t>(middle)] };
        if (value == target)
        {
            return middle;
        }
        if (value < target)
        {
            low = middle + 1;
        }
        else
        {
            high = middle - 1;
        }
    }
    return -1;
}

unitTests:
const std::vector<int> data{ 2, 5, 8, 12, 16, 23, 38, 56, 72, 91 };
TEST("finds values in the middle") { CHECK_EQ(binarySearch(data, 23), 5); CHECK_EQ(binarySearch(data, 12), 3); }
TEST("finds the first and last") { CHECK_EQ(binarySearch(data, 2), 0); CHECK_EQ(binarySearch(data, 91), 9); }
TEST("missing values") { CHECK_EQ(binarySearch(data, 1), -1); CHECK_EQ(binarySearch(data, 100), -1); CHECK_EQ(binarySearch(data, 13), -1); }
TEST("empty and single") { CHECK_EQ(binarySearch({}, 5), -1); CHECK_EQ(binarySearch({ 5 }, 5), 0); CHECK_EQ(binarySearch({ 5 }, 4), -1); }
TEST("fast on a big vector") { std::vector<int> big(2000000); for (std::size_t i{ 0 }; i < big.size(); ++i) big[i] = static_cast<int>(i) * 2; int found{ 0 }; for (int t{ 0 }; t < 200000; ++t) if (binarySearch(big, t * 20) >= 0) ++found; CHECK_EQ(found, 200000); }

